// ============================================================================
// Differential corpus tests for modes/interactive/components/diff.ts
//
// The corpus is generated by tools/gen-renderdiff-corpus.mjs, which *executes the upstream TypeScript
// file itself* (only its two imports are redirected) and records `renderDiff(diffText)`. Upstream reads
// the module-level `theme` singleton, so the generator stubs it with deterministic markers; the
// `MarkerTheme` below reproduces exactly those markers, which keeps every assertion about token choice
// and inverse-span placement while staying independent of terminal color resolution.
// ============================================================================

using System.Text.Json;
using Pi.CodingAgent.Modes.Interactive;
using Pi.CodingAgent.Modes.Interactive.Components;
using Pi.CodingAgent.Utils;
using Pi.Tui;
using Xunit;

namespace Pi.CodingAgent.Tests;

public sealed class RenderDiffCorpusTests
{
    private sealed record CorpusCase(string Diff, string Rendered);

    /// <summary>Mirrors the generator's `theme` stub: `fg → "<token>text</>"`, `inverse → "[inv]text[/inv]"`.</summary>
    private sealed class MarkerTheme : IRenderDiffTheme
    {
        public string Fg(string token, string text) => "<" + token + ">" + text + "</>";

        public string Inverse(string text) => "[inv]" + text + "[/inv]";
    }

    private static readonly MarkerTheme Theme = new();

    private static List<CorpusCase> Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "renderdiff-corpus.json");
        using var document = JsonDocument.Parse(File.ReadAllText(path));
        var cases = new List<CorpusCase>();
        foreach (var element in document.RootElement.GetProperty("cases").EnumerateArray())
        {
            cases.Add(new CorpusCase(
                element.GetProperty("diff").GetString()!,
                element.GetProperty("rendered").GetString()!));
        }

        return cases;
    }

    private static readonly List<CorpusCase> Corpus = Load();

    public static TheoryData<int> CaseIndexes()
    {
        var data = new TheoryData<int>();
        for (var i = 0; i < Corpus.Count; i++) data.Add(i);
        return data;
    }

    [Fact]
    public void Corpus_HasTheExpectedShape()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "renderdiff-corpus.json");
        using var document = JsonDocument.Parse(File.ReadAllText(path));
        Assert.Equal("8.0.4", document.RootElement.GetProperty("jsdiffVersion").GetString());
        Assert.Equal(
            "renderDiff(diffText) — default options",
            document.RootElement.GetProperty("api").GetString());
        Assert.Equal(83, Corpus.Count);
        // Every case is a whole `renderDiff` output, so a corpus that degenerated into a single
        // unparsable line per case would still "pass" — guard the shape instead.
        Assert.True(Corpus.Count(c => c.Rendered.Contains("<toolDiffRemoved>")) > 40);
        Assert.True(Corpus.Count(c => c.Rendered.Contains("[inv]")) > 25);
    }

    [Theory]
    [MemberData(nameof(CaseIndexes))]
    public void RenderDiff_MatchesTheUpstreamCorpus(int index)
    {
        var corpusCase = Corpus[index];
        Assert.Equal(corpusCase.Rendered, DiffRenderer.RenderDiff(corpusCase.Diff, null, Theme));
    }

    // ── pinned facts: the behaviours the corpus exercises most, stated so a failure names itself ─────

    [Fact]
    public void RenderDiff_ColoursContextRemovedAndAddedLines()
    {
        Assert.Equal(
            "<toolDiffContext> context</>\n" +
            "<toolDiffRemoved>-1 [inv]old[/inv]</>\n" +
            "<toolDiffAdded>+1 [inv]new[/inv]</>",
            DiffRenderer.RenderDiff(" context\n-1 old\n+1 new", null, Theme));
    }

    [Fact]
    public void RenderDiff_UsesIntraLineHighlightingOnlyForASingleLineSwap()
    {
        // Exactly one removed + one added → word-level inverse spans.
        Assert.Equal(
            "<toolDiffRemoved>-1 const x = [inv]1[/inv];</>\n<toolDiffAdded>+1 const x = [inv]2[/inv];</>",
            DiffRenderer.RenderDiff("-1 const x = 1;\n+1 const x = 2;", null, Theme));

        // Two removed + one added → the pairing rule does not apply, so lines are shown as-is.
        Assert.Equal(
            "<toolDiffRemoved>-1 a</>\n<toolDiffRemoved>-2 b</>\n<toolDiffAdded>+1 c</>",
            DiffRenderer.RenderDiff("-1 a\n-2 b\n+1 c", null, Theme));
    }

    [Fact]
    public void RenderDiff_DoesNotHighlightLeadingIndentation()
    {
        Assert.Equal(
            "<toolDiffRemoved>-1     indented = [inv]true[/inv];</>\n" +
            "<toolDiffAdded>+1     indented = [inv]false[/inv];</>",
            DiffRenderer.RenderDiff("-1     indented = true;\n+1     indented = false;", null, Theme));
    }

    [Fact]
    public void RenderDiff_ExpandsTabsToThreeSpaces()
    {
        // Tabs are expanded *before* the word diff, so the three spaces become the leading run that the
        // first-part whitespace strip peels off — leaving only `one`/`two` inverted.
        Assert.Equal(
            "<toolDiffRemoved>-1    [inv]one[/inv]</>\n<toolDiffAdded>+1    [inv]two[/inv]</>",
            DiffRenderer.RenderDiff("-1 \tone\n+1 \ttwo", null, Theme));
    }

    [Fact]
    public void RenderDiff_TreatsUnparsableLinesAsContext()
    {
        // `-` alone has no separating whitespace, so the pattern rejects it; `\ No newline…` has no
        // `[+-\s]` prefix at all; `123 no prefix` starts with a digit.
        Assert.Equal(
            "<toolDiffContext>-</>\n<toolDiffContext>\\ No newline at end of file</>\n" +
            "<toolDiffContext>123 no prefix</>",
            DiffRenderer.RenderDiff("-\n\\ No newline at end of file\n123 no prefix", null, Theme));
    }

    [Fact]
    public void RenderDiff_RejectsLinesContainingAStrayCarriageReturn()
    {
        // JS `.` refuses `\r`, and `$` is a hard end-of-string anchor, so a CRLF line never parses.
        Assert.Equal(
            "<toolDiffContext>-1 a\r</>\n<toolDiffContext>+1 b\r</>\n<toolDiffContext></>",
            DiffRenderer.RenderDiff("-1 a\r\n+1 b\r\n", null, Theme));
    }

    [Fact]
    public void RenderDiff_KeepsTheEmptyTrailingLineFromTheFinalNewline()
    {
        Assert.Equal(
            "<toolDiffRemoved>-1 [inv]a[/inv]</>\n<toolDiffAdded>+1 [inv]b[/inv]</>\n<toolDiffContext></>",
            DiffRenderer.RenderDiff("-1 a\n+1 b\n", null, Theme));
    }

    // ── ParseDiffLine / ReplaceTabs, pinned directly (the regex is the fidelity hot spot) ───────────

    [Theory]
    [InlineData("-123 content", "-", "123", "content")]
    [InlineData("+123 content", "+", "123", "content")]
    [InlineData(" 123 content", " ", "123", "content")]
    [InlineData("-  no number", "-", " ", "no number")]
    [InlineData("-  12 spaced", "-", "  12", "spaced")]
    [InlineData("-\t12 tab separated", "-", "\t12", "tab separated")]
    [InlineData("     ...", " ", "   ", "...")]
    [InlineData("+", null, null, null)]
    [InlineData("-", null, null, null)]
    [InlineData("", null, null, null)]
    [InlineData(" ... ", null, null, null)]
    [InlineData("123 no prefix", null, null, null)]
    [InlineData("-1 a\r", null, null, null)]
    public void ParseDiffLine_MatchesTheUpstreamPattern(string line, string? prefix, string? lineNum, string? content)
    {
        var parsed = DiffRenderer.ParseDiffLine(line);
        if (prefix is null)
        {
            Assert.Null(parsed);
            return;
        }

        Assert.NotNull(parsed);
        Assert.Equal(prefix, parsed!.Prefix);
        Assert.Equal(lineNum, parsed.LineNum);
        Assert.Equal(content, parsed.Content);
    }

    [Fact]
    public void ParseDiffLine_AcceptsTheFullJsWhitespaceSetAsThePrefix()
    {
        // JS `\s` (not .NET's `\s`): `\uFEFF` and `\u2028` are whitespace, `\u0085` is not.
        foreach (var ch in new[] { "\u00A0", "\u1680", "\u2003", "\u2028", "\u2029", "\u202F", "\u205F", "\u3000", "\uFEFF" })
        {
            var parsed = DiffRenderer.ParseDiffLine($"{ch}1 body");
            Assert.NotNull(parsed);
            Assert.Equal(ch, parsed!.Prefix);
            Assert.Equal("1", parsed.LineNum);
            Assert.Equal("body", parsed.Content);
        }

        Assert.Null(DiffRenderer.ParseDiffLine("\u00851 body"));
    }

    [Fact]
    public void ParseDiffLine_RejectsTheOtherJsLineTerminatorsInTheContent()
    {
        Assert.Null(DiffRenderer.ParseDiffLine("-1 a\u2028b"));
        Assert.Null(DiffRenderer.ParseDiffLine("-1 a\u2029b"));
        // …but `\u0085` is an ordinary character to JS, so this one parses.
        var parsed = DiffRenderer.ParseDiffLine("-1 a\u0085b");
        Assert.NotNull(parsed);
        Assert.Equal("a\u0085b", parsed!.Content);
    }

    [Fact]
    public void ReplaceTabs_ReplacesEveryTabWithThreeSpaces()
    {
        Assert.Equal(
            "a" + new string(' ', 3) + "b" + new string(' ', 9) + "c",
            DiffRenderer.ReplaceTabs("a\tb\t\t\tc"));
        Assert.Equal("no tabs", DiffRenderer.ReplaceTabs("no tabs"));
        Assert.Equal("", DiffRenderer.ReplaceTabs(""));
    }
}

/// <summary>
/// The production path: the public <c>RenderDiff</c> with the real theme runtime installed, so the
/// default theme adapter is exercised too (the corpus above deliberately bypasses it).
/// </summary>
public sealed class DiffRendererThemeTests : IDisposable
{
    private readonly bool? _previousChalk = Chalk.EnabledOverride;

    public DiffRendererThemeTests()
    {
        ThemeRuntime.ResetCachesForTests();
        Chalk.EnabledOverride = true;
        ThemeRuntime.InitTheme("dark", false, new ThemeSeams { ColorMode = TerminalColorMode.Truecolor });
    }

    public void Dispose()
    {
        Chalk.EnabledOverride = _previousChalk;
        ThemeRuntime.ResetCachesForTests();
    }

    [Fact]
    public void RenderDiff_ResolvesTheThreeDiffTokens()
    {
        var rendered = DiffRenderer.RenderDiff(" context\n-1 old\n+1 new");
        var lines = rendered.Split('\n');
        Assert.Equal(3, lines.Length);
        Assert.StartsWith(ThemeRuntime.Current.GetFgAnsi("toolDiffContext"), lines[0]);
        Assert.StartsWith(ThemeRuntime.Current.GetFgAnsi("toolDiffRemoved"), lines[1]);
        Assert.StartsWith(ThemeRuntime.Current.GetFgAnsi("toolDiffAdded"), lines[2]);
    }

    [Fact]
    public void RenderDiff_AppliesTheInverseStyleToChangedTokens()
    {
        // The single removed/added pair goes through the word diff, so both tokens are inverted.
        var rendered = DiffRenderer.RenderDiff("-1 old\n+1 new");
        Assert.Contains(ThemeRuntime.Current.Inverse("old"), rendered);
        Assert.Contains(ThemeRuntime.Current.Inverse("new"), rendered);
    }

    [Fact]
    public void RenderDiff_TreatsOmittedOptionsTheSameAsNull()
    {
        Assert.Equal(DiffRenderer.RenderDiff(" context", null), DiffRenderer.RenderDiff(" context"));
    }
}
